<?php

namespace App\Enums;

/**
 * What a stored version is. "upload" = a file as received (admin or, from Phase 4, client).
 * "signed" = a signed output generated by the Phase 5 signing workflow; it is added as a NEW version so
 * the signed source version is never overwritten.
 */
enum DocumentVersionKind: string
{
    use HasValues;

    case Upload = 'upload';
    case Signed = 'signed';
}
